import json
from page import page
imgs={}
T='#2e6475';A='#f6b31e';INK='#15191c';MU='#56666e';LINE='#d9e2e5'
sc=[('Key action','30%',9.5,'PHA-4 Standard with escapement: the best feel at this price'),('Piano sound','25%',8.5,'SuperNATURAL Piano with string and damper resonance'),('Value','15%',9.5,'$499.99 list, often less on sale'),('Speakers','10%',6.0,'2 × 6 W: fine for a bedroom, thin in a big room'),('Features','10%',6.5,'15 panel tones, Bluetooth MIDI, no Bluetooth audio'),('Portability','10%',8.5,'12.6 kg (27 lb 13 oz), 258 mm deep')]
rows=''.join(f'<div style="display:grid;grid-template-columns:200px 60px 1fr 70px;gap:14px;align-items:center;padding:11px 0;border-top:1px solid {LINE}"><div><div style="font-size:20px;font-weight:800">{n}</div><div style="font-size:14px;color:{MU}">{d}</div></div><div style="font-size:15px;color:{MU};font-weight:700">{w}</div><div style="height:18px;border-radius:99px;background:#e9eef0;overflow:hidden"><div style="height:100%;width:{v*10}%;background:{A if v>=8.5 else T};border-radius:99px"></div></div><div style="font-size:24px;font-weight:800;text-align:right">{v}</div></div>' for n,w,v,d in sc)
tot=sum(v*float(w[:-1])/100 for _,w,v,_ in sc)
body=f'''<div style="display:grid;grid-template-columns:270px 1fr;gap:20px"><div class="card" style="padding:26px;text-align:center;background:{INK};color:#fff;border:0;display:flex;flex-direction:column;justify-content:center"><div style="font-size:16px;letter-spacing:.12em;font-weight:800;color:{A}">OVERALL</div><div style="font-size:96px;font-weight:800;line-height:1">4.3</div><div style="font-size:22px;color:#c9d4d8">out of 5</div><div style="font-size:30px;color:{A};margin-top:10px;letter-spacing:4px">★★★★<span style="opacity:.35">★</span></div><div style="font-size:16px;color:#c9d4d8;margin-top:12px;line-height:1.4">Best key feel under $500</div><div style="font-size:15px;color:#9fb0b6;margin-top:6px">Weighted score 8.5 / 10</div></div>
<div class="card" style="padding:8px 22px 6px"><div style="display:grid;grid-template-columns:200px 60px 1fr 70px;gap:14px;font-size:13px;font-weight:800;color:{MU};letter-spacing:.08em;padding:8px 0">AREA<span>WEIGHT</span><span></span><span style="text-align:right">/10</span></div>{rows}</div></div>
<div style="margin-top:14px;font-size:16px;color:{MU}">Weighted score: key action and sound count most, because they matter most when you learn.</div>'''
imgs['roland-fp-10-review-score']=(830,page(830,'Verdict','Roland FP-10 review score',body,'Scores by Pianoers, October 2026'))
print('overall',tot,tot/2)
specs=[('Keys','88, PHA-4 Standard','Escapement and ivory feel'),('Touch','5 types + fixed','Match your playing strength'),('Sound','SuperNATURAL Piano','String, damper and key-off resonance'),('Polyphony','96 notes','Enough for pedalled pieces'),('Tones','15 on the panel','36 with the Roland Piano App'),('Speakers','2 × 6 W','12 cm speakers'),('Bluetooth','MIDI only (Ver 4.0)','No Bluetooth audio'),('USB','Type B to computer','Plus Type A for updates'),('Headphones','1 jack, 3.5 mm mini','Also works as an output'),('Pedal','Pedal switch included','Half-pedal with optional DP-10'),('Modes','Whole, Dual, Twin Piano','Twin Piano for lessons'),('Size and weight','1,284 × 258 × 140 mm','12.6 kg / 27 lb 13 oz')]
cells=''.join(f'<div class="card" style="padding:14px 16px"><div style="font-size:13px;font-weight:800;letter-spacing:.1em;color:{T}">{a.upper()}</div><div style="font-size:21px;font-weight:800;margin-top:3px;line-height:1.2">{b}</div><div style="font-size:15px;color:{MU};margin-top:3px">{c}</div></div>' for a,b,c in specs)
body=f'<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:12px">{cells}</div><div style="margin-top:14px;font-size:16px;color:{MU}">Size and weight with the music rest detached. Source: Roland FP-10 specifications.</div>'
imgs['roland-fp-10-specs']=(650,page(650,'Specs','Roland FP-10 at a glance',body,'Specifications checked on roland.com, October 2026'))
cols=['Roland FP-10','Yamaha P-145','Roland FP-30X']
rows=[('Key action','PHA-4 Standard','GHC','PHA-4 Standard'),('Escapement','Yes','No','Yes'),('Polyphony','96','64','256'),('Panel tones','15','10','56'),('Speakers','2 × 6 W','2 × 7 W','2 × 11 W'),('Bluetooth audio','No','P-145BT only','Yes'),('Bluetooth MIDI','Yes','No','Yes'),('Headphone jacks','1 (3.5 mm)','1','2 (3.5 mm + 6.3 mm)'),('Weight','12.6 kg','11.1 kg','14.8 kg*'),('Street price','$499.99','$499.99 (BT)','about $650–$700')]
win={('Escapement',0),('Escapement',2),('Polyphony',2),('Panel tones',2),('Speakers',2),('Bluetooth audio',2),('Bluetooth MIDI',0),('Bluetooth MIDI',2),('Headphone jacks',2),('Weight',1),('Street price',0),('Street price',1)}
th=''.join(f'<th style="text-align:left;padding:12px 14px;font-size:19px;{"background:#2e6475" if i==0 else ""}">{c}</th>' for i,c in enumerate(cols))
tr=''
for r in rows:
    tds=''.join(f'<td style="padding:10px 14px;font-size:17px;{"background:#eaf5ef;font-weight:700" if (r[0],i) in win else ""};{"border-left:3px solid #2e6475" if i==0 else ""}">{v}</td>' for i,v in enumerate(r[1:]))
    tr+=f'<tr style="border-top:1px solid {LINE}"><td style="padding:10px 14px;font-size:17px;font-weight:800">{r[0]}</td>{tds}</tr>'
body=f'<div class="card" style="overflow:hidden"><table style="width:100%;border-collapse:collapse"><thead><tr style="background:{INK};color:#fff"><th style="text-align:left;padding:12px 14px;font-size:15px">Spec</th>{th}</tr></thead><tbody>{tr}</tbody></table></div><div style="margin-top:12px;font-size:15px;color:{MU}">Green = better on that line. *FP-30X weight with music rest; others without. FP-10 and FP-30X: roland.com; P-145: Pianoers P-145 review. Prices October 2026.</div>'
imgs['roland-fp-10-vs-yamaha-p-145-vs-roland-fp-30x']=(790,page(790,'Compared','FP-10 vs P-145 vs FP-30X',body))
json.dump(imgs,open('imgs1.json','w'))
